const readingRU={oi:'Ана: Привет! Как дела?\nБиа: Всё хорошо! А у тебя?\nАна: Всё хорошо! До завтра!',nome:'Ана: Привет! Я Ана.\nПаулу: Меня зовут Паулу.\nАна: Приятно познакомиться, Паулу!',origem:'Меня зовут Ана. Я из России. Паулу из Бразилии.',estar:'Ана: Я дома. Я устала.\nПаулу: У меня всё хорошо.',artigos:'Это дом. Дом красивый. В доме есть книга.',nao:'Ана: Ты говоришь по-португальски?\nБиа: Я немного говорю.\nАна: Я говорю не очень много.',ter:'У Аны есть сестра. Сестре двадцать лет. У Паулу есть брат.',familia:'Это моя семья. Моего брата зовут Паулу. Мою сестру зовут Ана.',rotina:'Ана живёт в Бразилии. Она работает утром и изучает португальский вечером.',gostar:'Ане нравится музыка. Паулу нравится кофе. Им обоим нравится изучать португальский.',numeros:'Вода стоит три реала. Кофе стоит пять реалов. Ана покупает один кофе.',horas:'Библиотека открывается в девять. Ана договаривается о встрече в десять.',cafe:'Ана: Кофе и воду, пожалуйста.\nСотрудник кафе: Конечно!\nАна: Спасибо!',compras:'Футболка стоит двадцать реалов. Ана спрашивает: можно заплатить картой? Продавец отвечает: да.',onde:'Аптека находится рядом со школой. Рынок далеко. Ана ищет аптеку.',poder:'Ана: Я не поняла. Можете повторить медленнее?\nПаулу: Конечно!',saude:'У Аны болит голова. Она хочет записаться на приём на завтра.',telefone:'Привет, Паулу! Можешь прислать мне адрес? Давай встретимся завтра в десять. Ана.',amanha:'Завтра Ана будет учиться утром. Потом она выпьет кофе с Паулу.',ontem:'Вчера Ана ходила на рынок. Потом осталась дома и изучала португальский.',passado:'Вчера я работал утром. Купил хлеб и кофе. Вечером занимался португальским. Эти формы подходят и женщине.',imperfeito:'Когда я был ребёнком, жил рядом с пляжем. Вчера ходил на пляж с сестрой. Эти формы подходят и женщине.',comparar:'Автобус дешевле такси. Такси быстрее. Ана хочет сэкономить и выбирает автобус.',condicional:'Ана: Вы могли бы повторить адрес, пожалуйста?\nПаулу: Конечно!',conectores:'Хочу пойти на пляж, но идёт дождь. Поэтому я останусь дома и буду учиться.',opiniao:'Думаю, библиотека важна, потому что помогает жителям. Например, предлагает книги и встречи для чтения.',subjuntivo:'Завтра я буду работать. Если будет время, я позанимаюсь португальским. Потом отдохну.',email:'Доброе утро! Я хотела бы перенести своё занятие на пятницу. Вы могли бы подтвердить время? Спасибо. Ана.',resumo:'Объявление: библиотека сегодня закрыта. Обслуживание возобновится завтра в девять. Книги можно вернуть завтра.',conversa:'Паулу: Давай завтра в десять?\nАна: Я не поняла. Можешь повторить?\nПаулу: Завтра в десять.\nАна: Хорошо! До завтра!'};
const readingWords={artigos:[['esta','эта / это, с женским словом'],['há','есть / имеется'],['na','в: em + a']],nao:[['muito','много']],rotina:[['ela','она'],['estuda','изучает']],gostar:[['os dois','оба'],['gostam de','им нравится']],numeros:[['compra','покупает']],horas:[['abre','открывается'],['combina um encontro','договаривается о встрече']],cafe:[['atendente','сотрудник, обслуживающий клиента'],['claro','конечно']],compras:[['vinte','двадцать'],['pergunta','спрашивает'],['o vendedor','продавец'],['responde','отвечает'],['sim','да']],onde:[['procura','ищет']],poder:[['claro','конечно']],saude:[['ela quer','она хочет'],['para amanhã','на завтра']],telefone:[['vamos nos encontrar','давай встретимся']],amanha:[['depois','потом'],['tomar um café','выпить кофе'],['com','с']],ontem:[['foi','сходила / сходил, с ele или ela'],['ficou','осталась / остался, с ele или ela'],['estudou','изучала / изучал, с ele или ela']],passado:[['pão','хлеб']],imperfeito:[['perto da praia','рядом с пляжем']],comparar:[['quer economizar','хочет сэкономить'],['escolhe','выбирает'],['mais rápido','быстрее']],opiniao:[['importante','важный / важная'],['ajuda os moradores','помогает жителям'],['por exemplo','например'],['oferece','предлагает'],['livros','книги'],['encontros de leitura','встречи для чтения']],email:[['confirmar o horário','подтвердить время']],resumo:[['aviso','объявление'],['está fechada','закрыта'],['a devolução de livros','возврат книг'],['pode ser feita','может быть осуществлён']]};
function customWords(u){return Object.entries(u.customVocabulary||{}).slice(0,100).map(([id,w])=>({id,pt:String(w.pt||'').slice(0,100),ru:String(w.ru||'').slice(0,200),lesson:null}))}
function addCustom(u,pt,ru){pt=String(pt||'').trim().slice(0,100);ru=String(ru||'').trim().slice(0,200);if(!pt||!ru||!norm(pt))return false;u.customVocabulary??={};const id='custom:'+norm(pt);if(!u.customVocabulary[id]&&Object.keys(u.customVocabulary).length>=100)return false;u.customVocabulary[id]={pt,ru};u.vocabulary??={};u.vocabulary[id]={...u.vocabulary[id],saved:true};return true}
function vocabulary(id){const foundation=window.BoraBeginner?.units[id];if(foundation){const seen=new Set();return [...foundation.dictionary,...foundation.parts,...foundation.examples].filter(([pt])=>{const key=norm(pt);if(!key||seen.has(key))return false;seen.add(key);return true}).map(([pt,ru])=>({id:id+':'+norm(pt),lesson:id,pt,ru}));}const l=lessons().find(l=>l.id===id),r=rules[id],pairs=[...r[0],...(readingWords[id]||[]),...unit(id).words,...l.examples,...[unit(id).model]],seen=new Set();return pairs.filter(([pt])=>{const k=norm(pt);if(seen.has(k))return false;seen.add(k);return true}).map(([pt,ru])=>({id:id+':'+norm(pt),lesson:id,pt,ru}));}
function ruleHTML(id){const r=rules[id];return `<section class="phrase-lab"><h2>Фраза по кусочкам</h2><div class="phrase-pieces">${r[0].map(([pt,ru])=>`<span><b lang="pt-BR">${esc(pt)}</b><small>${esc(ru)}</small></span>`).join('')}</div><p>${esc(r[1])}</p><details><summary>Буквы и чтение</summary><p>${esc(r[2])}</p></details></section>`}
function audio(pt){return window.BoraAudio?.button(pt)||`<button class="audio-phrase" type="button" data-kit-speech="${esc(pt)}" aria-label="Послушать: ${esc(pt)}">▶ Слушать</button>`}
function wordsHTML(id,u){const words=vocabulary(id),state=u.vocabulary||{};return `<div class="lesson-word-grid">${words.map(w=>`<article class="word-card"><strong lang="pt-BR">${esc(w.pt)}</strong><p>${esc(w.ru)}</p>${audio(w.pt)}<button class="word-save" data-word-save="${esc(w.id)}" aria-pressed="${!!state[w.id]?.saved}">${state[w.id]?.saved?'✓ В моём словаре':'+ В мой словарь'}</button></article>`).join('')}</div>`}
function preview(u){const id=location.hash.split('?')[0].split('/')[1],l=lessons().find(l=>l.id===id);if(!l)return '<div class="panel"><h1>Занятие не найдено</h1><a href="#courses/pt">Все занятия</a></div>';const c=unit(id),r=u.courseProgress?.['pt/'+id],s=r?.guided,foundation=window.BoraBeginner?.units[id];if(foundation)return foundationPreview(u,l,foundation,s);return `<div class="narrow"><a class="back" href="#courses/pt">← Все занятия</a><section class="panel unit-preview"><span class="overline">УРОК ${lessons().indexOf(l)+1} · ${esc(l.module)}</span><h1>${esc(l.title)}</h1><img class="topic-illustration" src="/assets/scenes/${id}.svg" alt="${esc(l.scene)}" width="720" height="360"><h2>Чему научишься</h2><p>${esc(l.scene)}</p><h2>Как пройдёт занятие</h2><ol class="unit-plan"><li>Поймёшь правило: ${esc(c.rule)}</li><li>Разберёшь слова и послушаешь примеры.</li><li>Потренируешь слух, порядок слов и написание.</li><li>Подпишешь простую ситуацию и напишешь свой мини-текст.</li><li>Закрепишь тему пятью вопросами.</li></ol><div class="row"><a class="btn" href="#courses/pt/${id}">${s?.finishedAt&&s.index===18?'Открыть завершённое занятие':s?'Продолжить с шага '+(s.index+1):'Начать занятие'} →</a><a class="btn alt" href="#dictionary/${id}">Слова и правило</a></div>${s?.finishedAt?'<p>Занятие уже завершено. Внутри можно повторить его с начала.</p>':''}</section></div>`}
function foundationPreview(u,l,f,s){const updated=!!s&&s.version!==f.version,total=window.BoraLessons.activities(l).length;return `<div class="narrow"><a class="back" href="#courses/pt">← Все занятия</a><section class="panel unit-preview"><span class="overline">С САМОГО НУЛЯ · ЗАНЯТИЕ ${f.number} ИЗ 8</span><h1>${esc(l.title)}</h1><p>${esc(f.goal)}</p><p class="small">${esc(f.minutes)}</p><h2>Что будем делать</h2><ol class="unit-plan"><li>${f.words.length?'Разберём '+f.words.length+' новые слова или фразы.':'Вспомним знакомые фразы без новых слов.'}</li><li>Поймём устройство фразы и послушаем разговор.</li><li>Потренируемся с подсказками, затем проверим себя.</li></ol>${updated?'<p class="notice">Занятие обновлено. Прежние ответы сохранятся отдельно.</p>':''}<div class="row"><a class="btn" href="#courses/pt/${l.id}">${s&&!updated?s.finishedAt?'Повторить занятие':'Продолжить с шага '+Math.min(s.index+1,total):'Начать занятие'} →</a><a class="btn alt" href="#dictionary/${l.id}">Слова и правило</a></div></section></div>`;}
function dictionary(u){return window.BoraDictionary.page(u)}
function skipped(u){return lessons().filter(l=>!window.BoraBeginner?.units[l.id]||u.courseProgress?.['pt/'+l.id]?.guided?.version===window.BoraBeginner.units[l.id].version).flatMap(l=>Object.entries(u.courseProgress?.['pt/'+l.id]?.guided?.skipped||{}).filter(([,v])=>v).map(([index])=>({l,index:Number(index)})))}
function results(u){const all=lessons(),records=all.map(l=>u.courseProgress?.['pt/'+l.id]),done=all.filter((l,i)=>window.BoraBeginner?window.BoraBeginner.complete(u,l):records[i]?.done).length,answers=(u.learningHistory||[]).filter(a=>a.stage!=='write'),pending=skipped(u),saved=window.BoraDictionary?window.BoraDictionary.pool(u).filter(w=>w.aliases.some(id=>u.vocabulary?.[id]?.saved)).length:Object.values(u.vocabulary||{}).filter(w=>w.saved).length,known=window.BoraDictionary?window.BoraDictionary.pool(u).filter(w=>w.aliases.some(id=>u.vocabulary?.[id]?.lastKnown===true)).length:Object.values(u.vocabulary||{}).filter(w=>w.lastKnown===true).length,days=u.dailyPractice?Object.keys(u.dailyPractice).length:new Set((u.learningHistory||[]).map(a=>String(a.at).slice(0,10))).size;const bars=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const key=d.toISOString().slice(0,10),n=u.dailyPractice?.[key]??answers.filter(a=>String(a.at).slice(0,10)===key).length;return{key,n,label:d.toLocaleDateString('ru-RU',{weekday:'short'})}}),max=Math.max(1,...bars.map(b=>b.n));return `<section class="progress-hero"><div class="progress-ring" style="--progress:${done/all.length*100}%"><strong>${done}<small>из ${all.length}</small></strong></div><div><span class="overline">ТВОЙ ПУТЬ В БРАЗИЛИЮ</span><h1>Каждый шаг — ближе к разговору</h1><p>${done?'Продолжай в своём темпе. Пройденные темы можно повторять.':'Начни с первого занятия. Здесь появятся твои результаты.'}</p><a class="btn yellow" href="#home">Продолжить учиться →</a></div></section><div class="result-metrics"><article><strong>${saved}</strong><span>слов сохранено</span></article><article><strong>${known}</strong><span>вспомнил на карточках</span></article><article><strong>${days}</strong><span>дней практики за 90 дней</span></article><article><strong>${pending.length}</strong><span>заданий отложено</span></article></div>${pending.length?`<section class="panel"><h2>Вернуться к пропущенному</h2>${pending.map(({l,index})=>`<p><a href="#courses/pt/${l.id}" data-resume-step="${index}" data-resume-lesson="${l.id}">${esc(l.title)} · шаг ${index+1} →</a></p>`).join('')}</section>`:''}<section class="panel"><h2>Практика за 7 дней</h2><p class="small">Количество ответов в упражнениях, включая повторные попытки.</p><div class="activity-chart" role="img" aria-label="${bars.map(b=>b.label+': '+b.n+' ответов').join('; ')}">${bars.map(b=>`<div><span>${b.n}</span><i style="height:${Math.max(3,b.n/max*100)}px"></i><small>${esc(b.label)}</small></div>`).join('')}</div></section><section class="panel"><h2>Маршрут по темам</h2><div class="progress-map">${all.map((l,i)=>`<a class="${(window.BoraBeginner?window.BoraBeginner.complete(u,l):records[i]?.done)?'done':records[i]?.guided?'started':''}" href="#unit/${l.id}" aria-label="${esc(l.title)}: ${(window.BoraBeginner?window.BoraBeginner.complete(u,l):records[i]?.done)?'завершено':records[i]?.guided?'начато':'впереди'}"><b>${(window.BoraBeginner?window.BoraBeginner.complete(u,l):records[i]?.done)?'✓':i+1}</b><span>${esc(l.title)}</span></a>`).join('')}</div></section><section class="panel">${window.BoraAssess?.progress(u)||'<h2>Проверки знаний</h2><p>После закрепления темы здесь появятся оценки.</p>'}</section><p class="small">Завершение занятия и самопроверка слов не означают подтверждённый уровень языка.</p>`}
function bind(u,save,render){bindSpeech();const custom=document.querySelector('#custom-word-form');if(custom)custom.onsubmit=e=>{e.preventDefault();if(addCustom(u,document.querySelector('#custom-word-pt').value,document.querySelector('#custom-word-ru').value)){save();location.hash='dictionary/all?mode=saved';render()}else document.querySelector('#custom-word-status').textContent='Проверь слово и перевод. В словаре можно хранить до 100 своих слов.'};document.querySelectorAll('[data-word-save]').forEach(b=>b.onclick=()=>{const id=b.dataset.wordSave;u.vocabulary??={};const prev=u.vocabulary[id]||{};u.vocabulary[id]={...prev,saved:!prev.saved};save();render()});document.querySelectorAll('[data-resume-step]').forEach(b=>b.onclick=()=>{const r=u.courseProgress?.['pt/'+b.dataset.resumeLesson];if(r?.guided){r.guided.index=Number(b.dataset.resumeStep);u.currentLesson=b.dataset.resumeLesson;save()}});const f=document.querySelector('#dictionary-filter');if(f)f.onsubmit=e=>{e.preventDefault();location.hash='dictionary/'+document.querySelector('#dictionary-lesson').value+'?mode='+document.querySelector('#dictionary-mode').value+'&q='+encodeURIComponent(document.querySelector('#dictionary-query').value.trim())};document.querySelectorAll('[data-word-rate]').forEach(b=>b.onclick=()=>{const answer=document.querySelector('#word-answer');if(!answer?.open)return;u.vocabulary??={};const id=b.dataset.wordRate,prev=u.vocabulary[id]||{};u.vocabulary[id]={...prev,lastKnown:b.dataset.known==='1',reviews:(prev.reviews||0)+1,at:new Date().toISOString()};save();const params=new URLSearchParams(location.hash.split('?')[1]||'');params.set('i',String((Number(params.get('i'))||0)+1));location.hash=location.hash.split('?')[0]+'?'+params.toString()});const player=document.querySelector('#kit-player');if(player)document.querySelectorAll('[data-audio-id]').forEach(b=>b.onclick=async()=>{cancelSpeech();const a=[...Object.values(window.BoraAudioManifest||{}),...Object.values(window.BoraAudioExact||{})].find(a=>a.id===b.dataset.audioId);if(!a)return;player.hidden=false;player.src=a.src;document.querySelector('#kit-audio-status').textContent='';try{await player.play()}catch{document.querySelector('#kit-audio-status').textContent='Нажми ▶ в плеере.'}})}
function stop(){cancelSpeech();const p=document.querySelector('#kit-player');if(p){p.pause();p.removeAttribute('src');p.load()}}
window.BoraKit={cancelSpeech,audio,addCustom,readingRU,rules,vocabulary,ruleHTML,wordsHTML,preview,dictionary,results,skipped,bind,stop};
